#include "TrustSafetySystem.h"
#include <cctype>
#include <algorithm>
namespace NeoEngine { bool TrustSafetySystem::Valid(const std::string& id){if(id.empty()||id.size()>96)return false;for(unsigned char c:id)if(!std::isalnum(c)&&c!='-'&&c!='_'&&c!='.')return false;return true;} uint8_t TrustSafetySystem::Weight(FraudSignal s){return s==FraudSignal::DuplicateReceipt?3:5;} bool TrustSafetySystem::Report(std::string player,std::string event,FraudSignal signal){if(!Valid(player)||!Valid(event)||IsBanned(player)||!m_Events.insert(event).second)return false;auto& score=m_Scores[player];score=static_cast<uint8_t>(std::min<int>(255,score+Weight(signal)));m_Audit.push_back({player,event,signal,score});if(score>=8)m_Banned.insert(player);return true;} bool TrustSafetySystem::IsBanned(const std::string& player)const{return m_Banned.contains(player);}uint8_t TrustSafetySystem::Score(const std::string& player)const{auto it=m_Scores.find(player);return it==m_Scores.end()?0:it->second;}uint64_t TrustSafetySystem::DeterministicState()const{uint64_t h=1469598103934665603ULL;for(const auto& a:m_Audit){for(unsigned char c:a.playerId){h^=c;h*=1099511628211ULL;}for(unsigned char c:a.eventId){h^=c;h*=1099511628211ULL;}h^=static_cast<uint8_t>(a.signal);h*=1099511628211ULL;h^=a.score;h*=1099511628211ULL;}return h;} }
